QString InstanceId(const QJsonObject &request){return Id(request["group_id"].toString()+'-'+(request["role"]=="ecc"?QString("ecc"):Id(request["receiver_id"].toString())));}
void ExactSecret(const QString &path,const QByteArray &token){Require(token.size()==64 && QString::fromLatin1(token).contains(QRegularExpression("^[0-9a-f]{64}$")),"Invalid scoped service credential");if(QFile::exists(path))Require(Secret(path)==token,"Prepared service credential changed");else Write(path,token+'\n');}
QJsonObject FindGroup(const QJsonObject &manifest,const QString &id){for(const auto &value:manifest["groups"].toArray())if(value.toObject()["id"]==id)return value.toObject();throw std::runtime_error("Control group is not in this release");}
Endpoint LocalService(const QJsonObject &config){return {QString("http://%1:%2").arg(config["bind"].toString()).arg(config["port"].toInt()),QString(),Secret(config["credential_file"].toString())};}
QJsonObject ServiceGet(const QJsonObject &config,const QString &path){return Get(LocalService(config),path);}
