QJsonObject InitializeNode(const QString &root,const QString &programs,const QString &address,int port,const QString &dataDirectory){PrivateDirectory(root);Require(!QFile::exists(root+"/node.json"),"Node already initialized; reuse its existing configuration");Address(address,true);Port(port);Require(QDir::isAbsolutePath(dataDirectory) && QDir::cleanPath(dataDirectory)==dataDirectory,"Use an absolute local data directory");const auto node=QString::fromLatin1(Token().left(24));CreateCertificate(root,"getdaq-node-"+node);Write(root+"/agent.token",Token()+'\n');QJsonObject config{{"schema",1},{"kind","getdaq.node-agent"},{"node_id",node},{"root",root},{"program_directory",QDir(programs).absolutePath()},{"data_directory",dataDirectory},{"bind",address},{"port",port},{"credential_file",root+"/agent.token"},{"tls_certificate",root+"/tls.crt"},{"tls_key",root+"/tls.key"}};Write(root+"/node.json",Json(config));const auto code=QString::fromLatin1(Token().left(24));QJsonObject invitation{{"schema",1},{"node_id",node},{"url",QString("https://%1:%2").arg(address).arg(port)},{"certificate_sha256",CertificateFingerprint(root+"/tls.crt")},{"pairing_code",code},{"expires_ms",QDateTime::currentMSecsSinceEpoch()+15*60*1000}};Write(root+"/pairing.json",Json(invitation));return config;}
void RenewNodePairing(const QString &configuration){const auto config=Parse(Read(configuration));const auto root=config["root"].toString();PrivateDirectory(root);Require(!QFile::exists(root+"/master.json"),"An already paired node needs explicit master migration, not a new pairing code");const auto invitation=QJsonObject{{"schema",1},{"node_id",config["node_id"]},{"url",QString("https://%1:%2").arg(config["bind"].toString()).arg(config["port"].toInt())},{"certificate_sha256",CertificateFingerprint(config["tls_certificate"].toString())},{"pairing_code",QString::fromLatin1(Token().left(24))},{"expires_ms",QDateTime::currentMSecsSinceEpoch()+15*60*1000}};Write(root+"/pairing.json",Json(invitation));}
NodeAgent::NodeAgent(const QString &configuration,QObject *parent):QObject(parent),fConfig(Parse(Read(configuration))),fServer(this){Require(fConfig["schema"].toInt()==1 && fConfig["kind"]=="getdaq.node-agent","Unsupported node configuration");fRoot=fConfig["root"].toString();PrivateDirectory(fRoot);Require(QFileInfo(configuration).absoluteFilePath()==fRoot+"/node.json","Node configuration must be inside its private root");fPrograms=fConfig["program_directory"].toString();fData=fConfig["data_directory"].toString();fNode=Id(fConfig["node_id"].toString());fCredential=Secret(fConfig["credential_file"].toString());fLock.reset(new QLockFile(fRoot+"/agent.lock"));Require(fLock->tryLock(0),"Another node agent owns this working directory");PrivateDirectory(fRoot+"/operations");PrivateDirectory(fRoot+"/instances");PrivateDirectory(fRoot+"/objects");for(const auto &name:QDir(fRoot+"/operations").entryList({"*.json"},QDir::Files)){const auto path=fRoot+"/operations/"+name;auto record=Parse(Read(path));if(record["phase"]=="accepted" || record["phase"]=="running"){record["phase"]="unknown";record["message"]="Node agent restarted. Prior operations are not replayed; inspect original instance state.";Write(path,Json(record));}}connect(&fServer,&HttpServer::RequestSignal,this,&NodeAgent::Handle);}
NodeAgent::~NodeAgent(){fServer.close();QThreadPool::globalInstance()->waitForDone();}
void NodeAgent::Start(){fServer.SetTls(fConfig["tls_certificate"].toString(),fConfig["tls_key"].toString());Require(fServer.listen(QHostAddress(Address(fConfig["bind"].toString(),true)),quint16(Port(fConfig["port"].toInt()))),"Cannot listen on node management port");}
QJsonObject NodeAgent::Pair(const QJsonObject &request){if(QFile::exists(fRoot+"/master.json")){const auto previous=Parse(Read(fRoot+"/master.json"));Require(previous["pairing_request_sha256"].toString()==Sha(Json(request)) && previous["pairing_ack_until_ms"].toDouble()>QDateTime::currentMSecsSinceEpoch(),"This node is already paired; a consumed code cannot enroll another master");return {{"schema",1},{"node_id",fNode},{"credential",QString::fromLatin1(fCredential)},{"paired",true}};}const auto invitation=Parse(Read(fRoot+"/pairing.json"));Require(invitation["expires_ms"].toDouble()>QDateTime::currentMSecsSinceEpoch() && Sha(request["pairing_code"].toString().toUtf8())==Sha(invitation["pairing_code"].toString().toUtf8()),"Pairing code is invalid or expired");Endpoint repository{request["repository_url"].toString(),Digest(request["repository_certificate_sha256"].toString()),request["repository_token"].toString().toLatin1()};Require(QUrl(repository.url).scheme()=="https","Remote repository pairing requires HTTPS");Require(Get(repository,"/v1/identity")["repository_id"].toString()==Digest(request["repository_id"].toString()),"Master repository identity differs");ExactSecret(fRoot+"/repository.token",repository.credential);QJsonObject master{{"repository_url",repository.url},{"certificate_sha256",repository.certificateSha256},{"repository_id",request["repository_id"]},{"credential_file",fRoot+"/repository.token"},{"pairing_request_sha256",Sha(Json(request))},{"pairing_ack_until_ms",invitation["expires_ms"]}};Write(fRoot+"/master.json",Json(master));Require(QFile::remove(fRoot+"/pairing.json"),"Cannot consume pairing invitation");return {{"schema",1},{"node_id",fNode},{"credential",QString::fromLatin1(fCredential)},{"paired",true}};}
QJsonObject NodeAgent::Inventory()const{QJsonArray addresses,programs,instances;for(const auto &address:QNetworkInterface::allAddresses())if(address.protocol()==QAbstractSocket::IPv4Protocol)addresses.append(address.toString());for(const auto &name:{"getEccSoapServer","DataExporter","getdaq-sentry"}){const auto path=QDir(fPrograms).filePath(name);QJsonObject entry{{"name",name},{"installed",QFileInfo(path).isExecutable()}};if(QFileInfo(path).isExecutable())entry["sha256"]=Sha(Read(path,256*1024*1024));programs.append(entry);}for(const auto &name:QDir(fRoot+"/instances").entryList({"*.json"},QDir::Files)){auto entry=Parse(Read(fRoot+"/instances/"+name));QJsonArray pids;for(const auto &process:FindLocalServiceProcesses(entry["program"].toString(),entry["config_file"].toString()))pids.append(double(process.pid));if(entry["backend"]=="original-soap"){
 try{const auto service=Parse(Read(entry["config_file"].toString()));entry["configuration_repository"]=service["repository"];entry["working_directory"]=service["working_directory"];if(entry["role"]=="receiver")entry["data_directory"]=service["working_directory"];}catch(...){}
 pids=QJsonArray();try{pids=OriginalStatus(entry)["actual_pids"].toArray();}catch(...){}}entry["actual_pids"]=pids;entry.remove("checked_files");entry.remove("plan");entry.remove("plan_bytes");instances.append(entry);}return {{"schema",1},{"node_id",fNode},{"protocol",1},{"original_backends",true},{"addresses",addresses},{"program_directory",fPrograms},{"data_directory",fData},{"programs",programs},{"instances",instances}};}
QJsonObject NodeAgent::InstanceStatus(const QString &instance)const{const auto selected=Parse(Read(fRoot+"/instances/"+Id(instance)+".json"));if(selected["backend"]=="original-soap")return OriginalStatus(selected);const auto config=Parse(Read(selected["config_file"].toString()));QJsonArray pids;for(const auto &process:FindLocalServiceProcesses(selected["program"].toString(),selected["config_file"].toString()))pids.append(double(process.pid));Require(pids.size()==1,"Selected service does not have one matching live process");return {{"node_id",fNode},{"instance_id",instance},{"release_id",selected["release_id"]},{"group_sha256",selected["group_sha256"]},{"actual_pids",pids},{"identity",ServiceGet(config,"/v1/identity")},{"status",ServiceGet(config,"/v1/status")}};}
void NodeAgent::Handle(QString method,QString path,QByteArray body,HttpConnection *connection){try{if(method=="GET" && path=="/v1/identity"){connection->Reply(200,Json({{"schema",1},{"kind","getdaq.node-agent"},{"node_id",fNode},{"protocol",1},{"original_backends",true}}));return;}if(method=="POST" && path=="/v1/pair"){Require(!fBusy,"Node is busy");QScopedValueRollback<bool> pairing(fBusy,true);connection->Reply(200,Json(Pair(Parse(body))));return;}if(Sha(connection->RequestHeader("authorization"))!=Sha("Bearer "+fCredential)){connection->Reply(401,Json({{"error","Node authentication required"}}));return;}if(method=="GET" && path=="/v1/inventory"){connection->Reply(200,Json(Inventory()));return;}if(method=="GET" && path.startsWith("/v1/instances/") && path.endsWith("/status")){Require(fReads<8,"Too many pending instance observations");const auto instance=Id(path.mid(14,path.size()-21));++fReads;const QPointer<HttpConnection> target(connection);auto *watcher=new QFutureWatcher<QPair<QJsonObject,QString>>(this);connect(watcher,&QFutureWatcher<QPair<QJsonObject,QString>>::finished,this,[this,watcher,target]{const auto result=watcher->result();watcher->deleteLater();--fReads;if(target)target->Reply(result.second.isEmpty()?200:409,result.second.isEmpty()?Json(result.first):Json({{"error",result.second}}));});watcher->setFuture(QtConcurrent::run([this,instance]{try{return qMakePair(InstanceStatus(instance),QString());}catch(const std::exception &error){return qMakePair(QJsonObject(),QString::fromUtf8(error.what()));}}));return;}if(method=="GET" && path.startsWith("/v1/operations/")){const auto id=Id(path.mid(15));connection->Reply(200,Read(fRoot+"/operations/"+id+".json"));return;}Require(method=="POST" && path=="/v1/operations","Unsupported node request");const auto request=Parse(body);const QSet<QString> fields={"schema","operation_id","action","release_id","group_id","role","receiver_id","secrets","receiver_receipts","expected_previous","accepted_repair","ecc_stopped_confirmed"};for(auto it=request.begin();it!=request.end();++it)Require(fields.contains(it.key()),"Unsupported node operation field: "+it.key());Require(request["schema"].toInt()==1,"Invalid node operation schema");const auto id=Id(request["operation_id"].toString()),digest=Sha(body),file=fRoot+"/operations/"+id+".json";if(QFile::exists(file)){const auto record=Parse(Read(file));Require(record["request_sha256"]==digest,"Operation ID reused with different content");connection->Reply(202,Json(record));return;}Require(!fFault,"Node journal fault is held; inspect storage before new operations");Require(!fBusy,"Another node operation is active; requests are not queued");Require(QDir(fRoot+"/operations").entryList({"*.json"},QDir::Files).size()<8192,"Node operation budget reached; preserve and inspect records before further deployment");const auto action=request["action"].toString();Require(action=="prepare" || action=="activate" || action=="stop" || action=="terminate" || action=="release-terminated","Unsupported fixed node action");Digest(request["release_id"].toString());Id(request["group_id"].toString());Require(request["role"]=="ecc" || request["role"]=="receiver","Unknown instance role");InstanceId(request);QJsonObject record{{"schema",1},{"operation_id",id},{"request_sha256",digest},{"action",action},{"release_id",request["release_id"]},{"instance_id",InstanceId(request)},{"phase","accepted"}};Write(file,Json(record));connection->Reply(202,Json(record));fBusy=true;record["phase"]="running";Write(file,Json(record));auto *watcher=new QFutureWatcher<QJsonObject>(this);connect(watcher,&QFutureWatcher<QJsonObject>::finished,this,[this,watcher,file]{const auto result=watcher->result();watcher->deleteLater();try{Write(file,Json(result));}catch(const std::exception &error){fFault=true;qCritical().noquote()<<"Node journal fault; mutations held:"<<error.what();}fBusy=false;});watcher->setFuture(QtConcurrent::run([this,request,record]()mutable{bool effects=false;try{record["result"]=Execute(request,&effects);record["phase"]="complete";}catch(const std::exception &error){record["phase"]=effects?"unknown":"failed";record["message"]=QString::fromUtf8(error.what());}try{record["stage"]=Parse(Read(fRoot+"/operations/"+Id(request["operation_id"].toString())+".json"))["stage"];}catch(...){}return record;}));}catch(const std::exception &error){connection->Reply(409,Json({{"error",QString::fromUtf8(error.what())}}));}}
void NodeAgent::Progress(const QJsonObject &request,const QString &stage){CheckOperation();const auto file=fRoot+"/operations/"+Id(request["operation_id"].toString())+".json";auto record=Parse(Read(file));Require(record["phase"]=="running","Deployment operation is no longer running");record["stage"]=stage;record["updated_ms"]=double(QDateTime::currentMSecsSinceEpoch());Write(file,Json(record));}
QJsonObject NodeAgent::Execute(const QJsonObject &request,bool *effects){OperationScope operation(nullptr);const auto action=request["action"].toString();if(action=="prepare")return Prepare(request);if(action=="activate" || action=="stop" || action=="terminate"){
 const auto instance=InstanceId(request);const auto file=action=="activate"?fRoot+"/deployments/"+Digest(request["release_id"].toString())+'/'+instance+"/prepared.json":fRoot+"/instances/"+instance+".json";
 if(QFile::exists(file) && Parse(Read(file))["backend"]=="original-soap")return OriginalOperation(request,effects);
 }if(action=="activate")return Activate(request,effects);if(action=="release-terminated")return ReleaseTerminated(request,effects);return StopInstance(request,action=="terminate",effects);}
QJsonObject NodeAgent::Prepare(const QJsonObject &request){Progress(request,"Connecting to master configuration repository");const auto master=Parse(Read(fRoot+"/master.json"));const Endpoint repository{master["repository_url"].toString(),master["certificate_sha256"].toString(),Secret(master["credential_file"].toString())};const auto release=Digest(request["release_id"].toString());Require(Get(repository,"/v1/identity")["repository_id"]==master["repository_id"],"Repository identity changed");const auto response=Request(repository,"GET","/v1/deployments/"+release);Require(response.code==200 && Sha(response.body)==release,"Release manifest download differs");const auto manifest=Parse(response.body);ValidateRelease(manifest);bool assigned=false;for(const auto &host:manifest["hosts"].toArray())if(host.toObject()["id"]==fNode)assigned=true;Require(assigned,"This node is not assigned to the release");const auto local=fRoot+"/releases/"+release;PrivateDirectory(local);QMap<QString,QByteArray> files;QJsonArray mappings;int fileIndex=0;const int fileCount=manifest["files"].toArray().size();for(const auto &value:manifest["files"].toArray()){Progress(request,QString("Downloading and verifying configuration: %1 / %2 files").arg(++fileIndex).arg(fileCount));const auto file=value.toObject();QMap<QString,QByteArray> objects;for(const auto &part:file["objects"].toArray()){const auto sha=Digest(part.toString()),cached=fRoot+"/objects/"+sha;if(!QFile::exists(cached)){const auto received=Request(repository,"GET","/v1/content/"+sha);Require(received.code==200 && !received.body.isEmpty() && received.body.size()<=32768 && Sha(received.body)==sha,"Content download differs");Write(cached,received.body,true);}const auto bytes=Read(cached,32768);Require(Sha(bytes)==sha,"Cached object changed");objects[sha]=bytes;}const auto bytes=Assemble(file,objects);const auto name=Id(file["id"].toString()),path=local+'/'+name;Write(path,bytes,true);files[name]=bytes;mappings.append(QJsonObject{{"id",name},{"path",path},{"sha256",Sha(bytes)}});}Write(local+"/manifest.json",response.body,true);const auto group=FindGroup(manifest,request["group_id"].toString());Require(group["backend"]=="original-soap","Recreate this retired native group as original SOAP ECC / DataExporter.");ValidateGroupFiles(group,files);const auto instance=InstanceId(request),directory=fRoot+"/deployments/"+release+'/'+instance;PrivateDirectory(directory);PrivateDirectory(directory+"/credentials");PrivateDirectory(directory+"/state");PrivateDirectory(directory+"/logs");return PrepareOriginal(request,group,files,directory);
}
QJsonObject NodeAgent::Activate(const QJsonObject &,bool *) {
    throw std::runtime_error("Native ECC startup has been retired. Recreate this group with original SOAP ECC / DataExporter.");
}
QJsonObject NodeAgent::ReleaseTerminated(const QJsonObject &request,bool *effects) {
    Require(request["accepted_repair"].toBool(),"Explicit hardware-stop and data-preservation confirmation required");
    const auto instance=InstanceId(request),path=fRoot+"/instances/"+instance+".json";auto selected=Parse(Read(path));
    Require(selected["release_id"]==request["release_id"],"Inspection release differs from selected instance");
    Require(selected["phase"]=="terminated-needs-inspection" || selected["phase"]=="released-after-inspection","Only a terminated instance can be released after inspection");
    const auto config=selected["config_file"].toString(),program=selected["program"].toString();
    if(selected["backend"]=="original-soap")for(const auto &value:selected["processes"].toArray()){const auto object=value.toObject();LocalServiceProcess process;process.pid=qint64(object["pid"].toDouble());process.executable=object["executable"].toString();process.started=object["started"].toString().toLatin1();Require(!SameLocalServiceProcess(process),"An original ECC / DataExporter / monitor process is still active");}

    Require(QFileInfo(program).absolutePath()==fPrograms,"Inspection target installation differs");
    Require(FindLocalServiceProcesses(program,config).isEmpty(),"Backend process is still active; inspection release refused");
    Require(FindLocalReceiverProcesses(QDir(fPrograms).filePath("getdaq-receiver"),config).isEmpty(),"Receiver child is still active; inspection release refused");
    if(DeploymentInstanceReleased(selected)){selected.remove("checked_files");selected.remove("plan");selected.remove("plan_bytes");return selected;}
    const QJsonObject receipt{{"kind","getdaq.inspected-deployment-release"},{"instance_id",instance},{"release_id",request["release_id"]},{"operation_id",request["operation_id"]},
        {"previous_phase",selected["phase"]},{"operator_confirmed_stopped",true},{"data_preserved",true},{"no_matching_processes",true},
        {"hardware_state_source","operator confirmation; not inferred from process exit"},{"time_utc",QDateTime::currentDateTimeUtc().toString(Qt::ISODateWithMs)}};
    *effects=true;
    Write(QFileInfo(config).absolutePath()+"/inspection-release-"+Id(request["operation_id"].toString())+".json",Json(receipt),true);
    selected["inspection_release"]=receipt;selected["phase"]="released-after-inspection";selected["stopped"]=false;
    Write(path,Json(selected));selected.remove("checked_files");selected.remove("plan");selected.remove("plan_bytes");return selected;
}
QJsonObject NodeAgent::StopInstance(const QJsonObject &request,bool repair,bool *effects){const auto instance=InstanceId(request),path=fRoot+"/instances/"+instance+".json";auto selected=Parse(Read(path));Require(selected["release_id"]==request["release_id"],"Stop target release differs from selected instance");const auto configFile=selected["config_file"].toString(),program=selected["program"].toString();Require(QFileInfo(program).absolutePath()==fPrograms,"Stop target installation differs");const auto config=Parse(Read(configFile));auto processes=FindLocalServiceProcesses(program,configFile);const auto receivers=request["role"]=="receiver"?FindLocalReceiverProcesses(QDir(fPrograms).filePath("getdaq-receiver"),configFile):QVector<LocalServiceProcess>();if(!repair){if(processes.isEmpty())Require(selected["stopped"].toBool() && selected["phase"]=="stopped","Service is unavailable; cannot infer that its prior hardware/data session stopped. Inspect before changing deployment.");Require(receivers.isEmpty(),"Receiver processes are still active; finish acquisition first");if(!processes.isEmpty()){const auto identity=ServiceGet(config,"/v1/identity");if(request["role"]=="ecc")Require(identity["service_id"]==config["service_id"] && identity["snapshot_sha256"]==selected["snapshot_sha256"] && identity["input_binding_sha256"]==selected["input_binding_sha256"],"Stop target ECC identity differs");else Require(identity["agent_id"]==config["agent_id"] && identity["plan_sha256"]==selected["plan_sha256"],"Stop target receiver identity differs");const auto status=ServiceGet(config,"/v1/status");if(request["role"]=="ecc"){const auto controller=status["controller"].toObject();Require(!status["operation_active"].toBool() && !status["control_needs_reconciliation"].toBool() && !status["data_needs_reconciliation"].toBool() && !controller["outcome_unknown"].toBool() && !controller["needs_reconciliation"].toBool() && controller["state"].toInt()==1,"Return ECC to confirmed Idle before normal backend shutdown");}else{const auto lifecycle=status["lifecycle"].toObject();bool released=lifecycle["state"]=="fresh" && lifecycle["session_id"].toString().isEmpty() && lifecycle["receivers"].toArray().isEmpty();if(lifecycle["state"]=="stopped"){released=true;for(const auto &value:lifecycle["receivers"].toArray()){const auto receiver=value.toObject();released=released && receiver["reaped"].toBool() && receiver["seal_verified"].toBool() && receiver["exit_code"].toInt(-1)==0;}}Require(lifecycle.contains("needs_reconciliation") && !lifecycle["needs_reconciliation"].toBool() && released,"Receiving service has not completed its normal session finalization");}}}else Require(request["accepted_repair"].toBool(),"Explicit repair termination confirmation required");processes+=receivers;for(const auto &process:processes)if(SameLocalServiceProcess(process)){*effects=true;Require(!::kill(process.pid,SIGTERM),"Cannot signal selected instance");}for(int i=0;i<50;++i){bool remaining=false;for(const auto &process:processes)remaining=remaining||SameLocalServiceProcess(process);if(!remaining)break;QThread::msleep(100);}for(const auto &process:processes)Require(!SameLocalServiceProcess(process),"Process did not exit; it was not killed automatically");selected["phase"]=repair?"terminated-needs-inspection":"stopped";selected["stopped"]=!repair;Write(path,Json(selected));selected.remove("checked_files");selected.remove("plan");selected.remove("plan_bytes");return selected;}
